window.READING_REVIEW_DATA={"title":"Humans and Food","items":[{"id":"food-ebed3ee3c728","term":"seismic","type":"word","ipa":"ˈsaɪzmɪk","pos":"adj. 形容词","stars":5,"zh":"重大而深刻的","contextSenses":[0],"legacyId":"seismic|重大而深刻的","note":"常见义：地震的；剧烈的；学习用法：seismic change 根本性变化；辨析：本句是比喻，不是发生三次地震","examples":[{"en":"During the journey from our hunter-gatherer ancestors to the present day, there have been three seismic changes that have impacted the food we eat: the discovery of cooking, the emergence of agriculture, and the invention of methods of preserving food.","zh":"从狩猎采集的祖先走到今天，人类经历了三次深刻影响所吃食物的重大变化：发现烹饪、农业出现，以及发明保存食物的方法。","sourceId":"A1","source":"original","number":1,"paragraph":"A"}],"para":"A","memory":{"method":"语义＋词族","parts":"seismic 与 seismology（地震学）联记","tip":"本篇 seismic change 是“地震般深刻的变化”，不是实际地震。","family":"seismology 地震学；a seismic shift 巨变"}},{"id":"food-13734d5a13e1","term":"emergence","type":"word","ipa":"ɪˈmɜːdʒəns","pos":"n. 名词","stars":4,"zh":"出现，兴起","contextSenses":[0],"legacyId":"emergence|出现，兴起","note":"常见义：出现；显现；学习用法：新技术或行业的兴起；辨析：与 emergency 紧急情况不同","examples":[{"en":"During the journey from our hunter-gatherer ancestors to the present day, there have been three seismic changes that have impacted the food we eat: the discovery of cooking, the emergence of agriculture, and the invention of methods of preserving food.","zh":"从狩猎采集的祖先走到今天，人类经历了三次深刻影响所吃食物的重大变化：发现烹饪、农业出现，以及发明保存食物的方法。","sourceId":"A1","source":"original","number":1,"paragraph":"A"}],"para":"A","memory":{"method":"词族变化","parts":"emerge（出现）→ emergence（出现，名词）","tip":"新事物出现、兴起；与 emergency（紧急情况）区分。","family":"emerge 出现；emergent 新兴的"}},{"id":"food-d5a96f2bc582","term":"preserve","type":"word","ipa":"prɪˈzɜːv","pos":"v. 动词","stars":4,"zh":"保存食物，防止变质","contextSenses":[0],"legacyId":"preserve|保存食物，防止变质","note":"常见义：保护；保存；保持；学习用法：保存食物；保护遗产或环境；辨析：preserve order 维持秩序，不是冷藏秩序","examples":[{"en":"During the journey from our hunter-gatherer ancestors to the present day, there have been three seismic changes that have impacted the food we eat: the discovery of cooking, the emergence of agriculture, and the invention of methods of preserving food.","zh":"从狩猎采集的祖先走到今天，人类经历了三次深刻影响所吃食物的重大变化：发现烹饪、农业出现，以及发明保存食物的方法。","sourceId":"A1","source":"original","number":1,"paragraph":"A"}],"para":"A","memory":{"method":"词族联想","parts":"preserve（保存）→ preservation（保存、保护）","tip":"本篇是保存食物；与冷冻 freeze、罐藏 canning 建立语义联系。","family":"preservation 保存；preservative 防腐剂"}},{"id":"food-d5f0bb1e269d","term":"discovery","type":"word","ipa":"dɪˈskʌvəri","pos":"n. 名词","stars":3,"zh":"发现","contextSenses":[0],"legacyId":"discovery|发现","note":"常见义：发现；被发现的事物；学习用法：科学发现；discovery of… 对……的发现；辨析：与 invention 发明不同，发现不一定是创造新物品","examples":[{"en":"The 19th-century scientist Charles Darwin thought that cooking, after language, was the greatest discovery made by man.","zh":"十九世纪科学家查尔斯 达尔文认为，烹饪是人类仅次于语言的最伟大发现。","sourceId":"A2","source":"original","number":2,"paragraph":"A"}],"para":"A"},{"id":"food-e8821d7e03e4","term":"after","type":"word","ipa":"ˈɑːftə","pos":"prep. 介词","stars":1,"zh":"重要性上仅次于语言","contextSenses":[0],"legacyId":"after|重要性上仅次于语言","note":"常见义：在……之后；次于；学习用法：时间顺序；排名次序；辨析：此处强调地位或排序，不能直接推成发现时间先后","examples":[{"en":"The 19th-century scientist Charles Darwin thought that cooking, after language, was the greatest discovery made by man.","zh":"十九世纪科学家查尔斯 达尔文认为，烹饪是人类仅次于语言的最伟大发现。","sourceId":"A2","source":"original","number":2,"paragraph":"A"}],"para":"A"},{"id":"food-825aa45d5a8a","term":"raw","type":"word","ipa":"rɔː","pos":"adj. 形容词","stars":2,"zh":"生的，未经烹饪的","contextSenses":[0],"legacyId":"raw|生的，未经烹饪的","note":"常见义：生的；原始的；未加工的；学习用法：raw materials 原材料；raw data 原始数据；辨析：不是所有 raw 都指生食","examples":[{"en":"All of us eat some raw food, such as fruit and vegetables, but the great majority of food we consume is cooked.","zh":"我们每个人都吃一些生食，例如水果和蔬菜，但我们所吃食物的绝大部分是熟食。","sourceId":"A3","source":"original","number":3,"paragraph":"A"}],"para":"A"},{"id":"food-3020b07f58ee","term":"consume","type":"word","ipa":"kənˈsjuːm","pos":"v. 动词","stars":4,"zh":"食用","contextSenses":[0],"legacyId":"consume|食用","note":"常见义：消耗；消费；吃喝；学习用法：消耗能源；消费商品；食用食物；辨析：消费行为与吃喝由宾语决定","examples":[{"en":"All of us eat some raw food, such as fruit and vegetables, but the great majority of food we consume is cooked.","zh":"我们每个人都吃一些生食，例如水果和蔬菜，但我们所吃食物的绝大部分是熟食。","sourceId":"A3","source":"original","number":3,"paragraph":"A"}],"para":"A","memory":{"method":"词族变化","parts":"consume（消耗、食用）→ consumption（消耗、食用）","tip":"吃食物也是消耗食物；同一词还可说消耗能源。","family":"consumption 消费／消耗；consumer 消费者"}},{"id":"food-55e759620c32","term":"inedible","type":"word","ipa":"ɪnˈedɪbəl","pos":"adj. 形容词","stars":3,"zh":"不能食用的","contextSenses":[0],"legacyId":"inedible|不能食用的","note":"常见义：不可食用的；学习用法：edible/inedible 可食用与不可食用；辨析：in- 在此否定；不能与 incredible 混淆","examples":[{"en":"Cooking can turn plants that are inedible into edible food by destroying toxic chemicals that plants often manufacture to protect themselves against attack by insects or other herbivorous animals.","zh":"烹饪可以破坏植物常常制造、用来抵御昆虫或其他食草动物攻击的有毒化学物质，从而把不可食用的植物变成可食用的食物。","sourceId":"A4","source":"original","number":4,"paragraph":"A"}],"para":"A"},{"id":"food-3d8f8c8b8008","term":"toxic","type":"word","ipa":"ˈtɒksɪk","pos":"adj. 形容词","stars":3,"zh":"有毒的","contextSenses":[0],"legacyId":"toxic|有毒的","note":"常见义：有毒的；有害的；学习用法：toxic chemicals 有毒化学物质；辨析：可比喻有害的人际环境；此处为实际毒性","examples":[{"en":"Cooking can turn plants that are inedible into edible food by destroying toxic chemicals that plants often manufacture to protect themselves against attack by insects or other herbivorous animals.","zh":"烹饪可以破坏植物常常制造、用来抵御昆虫或其他食草动物攻击的有毒化学物质，从而把不可食用的植物变成可食用的食物。","sourceId":"A4","source":"original","number":4,"paragraph":"A"}],"para":"A"},{"id":"food-3ecb4011b4d4","term":"manufacture","type":"word","ipa":"ˌmænjʊˈfæktʃə","pos":"v. 动词","stars":3,"zh":"植物产生化学物质","contextSenses":[0],"legacyId":"manufacture|植物产生化学物质","note":"常见义：制造；生产；学习用法：工厂生产；生物合成物质；辨析：主语为植物时不必译成工厂制造","examples":[{"en":"Cooking can turn plants that are inedible into edible food by destroying toxic chemicals that plants often manufacture to protect themselves against attack by insects or other herbivorous animals.","zh":"烹饪可以破坏植物常常制造、用来抵御昆虫或其他食草动物攻击的有毒化学物质，从而把不可食用的植物变成可食用的食物。","sourceId":"A4","source":"original","number":4,"paragraph":"A"}],"para":"A"},{"id":"food-514e7ad00ef5","term":"refer to as","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"称为","contextSenses":[0],"legacyId":"refer to as|称为","note":"常见义：把……称作；学习用法：be referred to as 被称为；辨析：refer to 也可指提及或查阅，此处有 as 才是命名","examples":[{"en":"These toxic chemicals are referred to as “plant secondary compounds” because they are not directly involved in the plant's normal growth, development, and reproduction, and are produced purely as chemical defenses.","zh":"这些有毒化学物质被称为植物次生化合物，因为它们不直接参与植物的正常生长、发育与繁殖，而完全是作为化学防御物质产生的。","sourceId":"A5","source":"original","number":5,"paragraph":"A"}],"para":"A"},{"id":"food-c5f7a03bf1ad","term":"compound","type":"word","ipa":"ˈkɒmpaʊnd","pos":"n. 名词","stars":3,"zh":"化合物","contextSenses":[0],"legacyId":"compound|化合物","note":"常见义：化合物；复合物；复合的；学习用法：chemical compound 化合物；辨析：动词 compound a problem 使问题加重","examples":[{"en":"These toxic chemicals are referred to as “plant secondary compounds” because they are not directly involved in the plant's normal growth, development, and reproduction, and are produced purely as chemical defenses.","zh":"这些有毒化学物质被称为植物次生化合物，因为它们不直接参与植物的正常生长、发育与繁殖，而完全是作为化学防御物质产生的。","sourceId":"A5","source":"original","number":5,"paragraph":"A"}],"para":"A"},{"id":"food-dedc3a9d0c07","term":"be involved in","type":"phrase","ipa":"","pos":"短语／搭配","stars":4,"zh":"参与","contextSenses":[0],"legacyId":"be involved in|参与","note":"常见义：涉及；参与；学习用法：参与研究或过程；辨析：不是只指被卷入坏事","examples":[{"en":"These toxic chemicals are referred to as “plant secondary compounds” because they are not directly involved in the plant's normal growth, development, and reproduction, and are produced purely as chemical defenses.","zh":"这些有毒化学物质被称为植物次生化合物，因为它们不直接参与植物的正常生长、发育与繁殖，而完全是作为化学防御物质产生的。","sourceId":"A5","source":"original","number":5,"paragraph":"A"}],"para":"A"},{"id":"food-6110c2d4a716","term":"bitter","type":"word","ipa":"ˈbɪtə","pos":"adj. 形容词","stars":3,"zh":"苦的","contextSenses":[0],"legacyId":"bitter|苦的","note":"常见义：苦味的；痛苦的；激烈的；学习用法：bitter taste 苦味；bitter dispute 激烈争执；辨析：a bitter experience 痛苦经历，不是食物味道","examples":[{"en":"They give many of the plants we consume, such as coffee or Brussels sprouts, their bitter taste.","zh":"它们使我们食用的许多植物，例如咖啡或抱子甘蓝，带有苦味。","sourceId":"A6","source":"original","number":6,"paragraph":"A"}],"para":"A"},{"id":"food-65077645fcd0","term":"give","type":"word","ipa":"ɡɪv","pos":"v. 动词","stars":1,"zh":"使植物具有某种味道","contextSenses":[0],"legacyId":"give|使植物具有某种味道","note":"常见义：给予；赋予；造成；学习用法：give sb confidence 使人有信心；辨析：本句 give A B 是赋予特征，不是把东西递给某人","examples":[{"en":"They give many of the plants we consume, such as coffee or Brussels sprouts, their bitter taste.","zh":"它们使我们食用的许多植物，例如咖啡或抱子甘蓝，带有苦味。","sourceId":"A6","source":"original","number":6,"paragraph":"A"}],"para":"A"},{"id":"food-53e306370c6f","term":"digestible","type":"word","ipa":"daɪˈdʒestəbəl","pos":"adj. 形容词","stars":4,"zh":"容易消化的","contextSenses":[0],"legacyId":"digestible|容易消化的","note":"常见义：可消化的；易理解的；学习用法：营养话题中的易消化；辨析：digestible information 可指易理解的信息","examples":[{"en":"Cooked food is often more digestible because heat breaks down tough cellulose cell walls in plants or tough connective tissue in animals.","zh":"熟食往往更容易消化，因为加热会分解植物中坚韧的纤维素细胞壁，或动物中坚韧的结缔组织。","sourceId":"B1","source":"original","number":7,"paragraph":"B"}],"para":"B","memory":{"method":"词干＋后缀","parts":"digest（消化）＋-ible（可……的）","tip":"可被消化的；inedible 不能食用与 indigestible 难消化不同。","family":"digest 消化；indigestible 难消化的"}},{"id":"food-7734d490c8b6","term":"break down","type":"phrase","ipa":"","pos":"短语／搭配","stars":4,"zh":"分解","contextSenses":[0],"legacyId":"break down|分解","note":"常见义：分解；出故障；崩溃；学习用法：分解材料；分析问题；机器故障；辨析：本句不是设备坏了","examples":[{"en":"Cooked food is often more digestible because heat breaks down tough cellulose cell walls in plants or tough connective tissue in animals.","zh":"熟食往往更容易消化，因为加热会分解植物中坚韧的纤维素细胞壁，或动物中坚韧的结缔组织。","sourceId":"B1","source":"original","number":7,"paragraph":"B"}],"para":"B"},{"id":"food-eb32f56d9b1f","term":"tissue","type":"word","ipa":"ˈtɪʃuː","pos":"n. 名词","stars":3,"zh":"组织，动物体内组织","contextSenses":[0],"legacyId":"tissue|组织，动物体内组织","note":"常见义：组织；薄纸；纸巾；学习用法：人体或生物组织；辨析：不是一张面巾纸，依语境选义","examples":[{"en":"Cooked food is often more digestible because heat breaks down tough cellulose cell walls in plants or tough connective tissue in animals.","zh":"熟食往往更容易消化，因为加热会分解植物中坚韧的纤维素细胞壁，或动物中坚韧的结缔组织。","sourceId":"B1","source":"original","number":7,"paragraph":"B"}],"para":"B"},{"id":"food-11ac17b8a5d7","term":"equivalent","type":"word","ipa":"ɪˈkwɪvələnt","pos":"n. 名词","stars":4,"zh":"对应的熟食","contextSenses":[0],"legacyId":"equivalent|对应的熟食","note":"常见义：相等的；等价物；学习用法：equivalent amount 同等数量；对应物；辨析：本句作名词，不是另一个形容词修饰 food","examples":[{"en":"Chewing raw turnip, a plate of uncooked rice, or a raw leg of lamb is much harder work than eating the cooked equivalent.","zh":"咀嚼生芜菁、一盘未煮熟的米饭或一只生羊腿，比吃相应的熟食费力得多。","sourceId":"B2","source":"original","number":8,"paragraph":"B"}],"para":"B","memory":{"method":"词族联想","parts":"equivalent（等同的、对应物）→ equivalence（等价）","tip":"本篇 cooked equivalent 是同一种食物对应的熟食。","family":"equivalence 等价；equivalent to 相当于"}},{"id":"food-fd21ccea847b","term":"work","type":"word","ipa":"wɜːk","pos":"n. 名词","stars":2,"zh":"费力的活动","contextSenses":[0],"legacyId":"work|费力的活动","note":"常见义：工作；劳动；作品；学习用法：hard work 艰苦劳动；运作；辨析：这里不是职业工作，work 不可数","examples":[{"en":"Chewing raw turnip, a plate of uncooked rice, or a raw leg of lamb is much harder work than eating the cooked equivalent.","zh":"咀嚼生芜菁、一盘未煮熟的米饭或一只生羊腿，比吃相应的熟食费力得多。","sourceId":"B2","source":"original","number":8,"paragraph":"B"}],"para":"B"},{"id":"food-09a46bbd0064","term":"expend","type":"word","ipa":"ɪkˈspend","pos":"v. 动词","stars":3,"zh":"消耗，花费能量","contextSenses":[0],"legacyId":"expend|消耗，花费能量","note":"常见义：花费；耗用；学习用法：expend energy/resources 消耗能量或资源；辨析：区别 expand 扩大，拼写与意义都不同","examples":[{"en":"The energy expended in chewing to break down the tough material is replaced by energy from the fuel used in cooking the food, so the ratio of energy gained to energy expended by the body is greater when food is cooked.","zh":"原本通过咀嚼来分解坚韧材料所消耗的能量，改由烹饪时使用的燃料所提供的能量承担；因此，食物煮熟后，身体获得的能量与自身消耗的能量之比更高。","sourceId":"B3","source":"original","number":9,"paragraph":"B"}],"para":"B"},{"id":"food-82d8268c42eb","term":"ratio","type":"word","ipa":"ˈreɪʃiəʊ","pos":"n. 名词","stars":3,"zh":"比值，比例","contextSenses":[0],"legacyId":"ratio|比值，比例","note":"常见义：两种量之比；学习用法：the ratio of A to B A与B之比；辨析：不等于 rate 速率；A、B顺序不能颠倒","examples":[{"en":"The energy expended in chewing to break down the tough material is replaced by energy from the fuel used in cooking the food, so the ratio of energy gained to energy expended by the body is greater when food is cooked.","zh":"原本通过咀嚼来分解坚韧材料所消耗的能量，改由烹饪时使用的燃料所提供的能量承担；因此，食物煮熟后，身体获得的能量与自身消耗的能量之比更高。","sourceId":"B3","source":"original","number":9,"paragraph":"B"}],"para":"B"},{"id":"food-c036cf70b8cc","term":"gain","type":"word","ipa":"ɡeɪn","pos":"v./n. 动词／名词","stars":2,"zh":"获得能量","contextSenses":[0],"legacyId":"gain|获得能量","note":"常见义：获得；增加；收益；学习用法：gain knowledge 获得知识；energy gain 能量获取；辨析：名词 gains 可指增长或收益","examples":[{"en":"The energy expended in chewing to break down the tough material is replaced by energy from the fuel used in cooking the food, so the ratio of energy gained to energy expended by the body is greater when food is cooked.","zh":"原本通过咀嚼来分解坚韧材料所消耗的能量，改由烹饪时使用的燃料所提供的能量承担；因此，食物煮熟后，身体获得的能量与自身消耗的能量之比更高。","sourceId":"B3","source":"original","number":9,"paragraph":"B"}],"para":"B"},{"id":"food-659372e21620","term":"up to","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"最多可达","contextSenses":[0],"legacyId":"up to|最多可达","note":"常见义：多达；直到；由……决定；学习用法：数量上限；up to seven hours 至多七小时；辨析：不是每个人每天恰好七小时","examples":[{"en":"Until the development of agriculture, hunter-gatherers spent up to seven hours a day gathering food.","zh":"农业出现以前，狩猎采集者每天最多要花七个小时获取食物。","sourceId":"C1","source":"original","number":10,"paragraph":"C"}],"para":"C"},{"id":"food-9852196a9033","term":"gather","type":"word","ipa":"ˈɡæðə","pos":"v. 动词","stars":2,"zh":"采集食物","contextSenses":[0],"legacyId":"gather|采集食物","note":"常见义：收集；聚集；学习用法：gather information 收集信息；辨析：gather that… 可指推断得知","examples":[{"en":"Until the development of agriculture, hunter-gatherers spent up to seven hours a day gathering food.","zh":"农业出现以前，狩猎采集者每天最多要花七个小时获取食物。","sourceId":"C1","source":"original","number":10,"paragraph":"C"}],"para":"C"},{"id":"food-a54f79b40e65","term":"advent","type":"word","ipa":"ˈædvent","pos":"n. 名词","stars":3,"zh":"出现，到来","contextSenses":[0],"legacyId":"advent|出现，到来","note":"常见义：重要事物的出现；学习用法：with the advent of technology 随着技术出现；辨析：通常不用于普通人的日常到访","examples":[{"en":"This all began to change around 10,500 years ago with the advent of farming, which led to dramatic changes in human societies.","zh":"大约一万零五百年前，随着农业的出现，这一切开始改变，并由此引发了人类社会的重大变化。","sourceId":"C2","source":"original","number":11,"paragraph":"C"}],"para":"C"},{"id":"food-c366dda80ac6","term":"dramatic","type":"word","ipa":"drəˈmætɪk","pos":"adj. 形容词","stars":3,"zh":"重大且显著的","contextSenses":[0],"legacyId":"dramatic|重大且显著的","note":"常见义：戏剧的；显著的；学习用法：dramatic change/increase 显著变化或增长；辨析：本句不是戏剧表演","examples":[{"en":"This all began to change around 10,500 years ago with the advent of farming, which led to dramatic changes in human societies.","zh":"大约一万零五百年前，随着农业的出现，这一切开始改变，并由此引发了人类社会的重大变化。","sourceId":"C2","source":"original","number":11,"paragraph":"C"}],"para":"C"},{"id":"food-3ad3bb258cbf","term":"aid","type":"word","ipa":"eɪd","pos":"v. 动词","stars":2,"zh":"帮助生存","contextSenses":[0],"legacyId":"aid|帮助生存","note":"常见义：帮助；援助；学习用法：aid development 促进发展；financial aid 经济援助；辨析：aid 可直接作及物动词，后接 survival","examples":[{"en":"People began to create a variety of new tools to aid survival, and in turn, populations increased in size.","zh":"人们开始创造多种新工具来帮助生存，人口规模也随之增加。","sourceId":"C3","source":"original","number":12,"paragraph":"C"}],"para":"C"},{"id":"food-d9174230a8eb","term":"in turn","type":"phrase","ipa":"","pos":"短语／搭配","stars":4,"zh":"继而，随之","contextSenses":[0],"legacyId":"in turn|继而，随之","note":"常见义：依次；反过来；相应地；学习用法：描述连锁影响；辨析：不是这里的轮流排队","examples":[{"en":"People began to create a variety of new tools to aid survival, and in turn, populations increased in size.","zh":"人们开始创造多种新工具来帮助生存，人口规模也随之增加。","sourceId":"C3","source":"original","number":12,"paragraph":"C"}],"para":"C"},{"id":"food-26dcdd160c92","term":"specialization","type":"word","ipa":"ˌspeʃəlaɪˈzeɪʃən","pos":"n. 名词","stars":4,"zh":"专业化分工","contextSenses":[0],"legacyId":"specialization|专业化分工","note":"常见义：专门化；专业化；学习用法：division of labour 劳动分工；专业领域聚焦；辨析：不是仅指大学选择专业","examples":[{"en":"These changes led to the possibility of specialization of different tasks within society.","zh":"这些变化使社会内部不同任务的专业分工成为可能。","sourceId":"C4","source":"original","number":13,"paragraph":"C"}],"para":"C","memory":{"method":"派生构词","parts":"specialize（专门从事）去 e 后接 -ation","tip":"不同的人专门做不同任务，即专业化分工。","family":"specialist 专家；specialisation 英式拼写"},"acceptedSpellings":["specialization","specialisation"]},{"id":"food-dbc25c8f0c35","term":"lead to","type":"phrase","ipa":"","pos":"短语／搭配","stars":4,"zh":"导致，使成为可能","contextSenses":[0],"legacyId":"lead to|导致，使成为可能","note":"常见义：通向；导致；学习用法：引出结果；result in 同义替换；辨析：to 为介词，后接名词或动名词","examples":[{"en":"These changes led to the possibility of specialization of different tasks within society.","zh":"这些变化使社会内部不同任务的专业分工成为可能。","sourceId":"C4","source":"original","number":13,"paragraph":"C"}],"para":"C"},{"id":"food-df164229c88b","term":"sophisticated","type":"word","ipa":"səˈfɪstɪkeɪtɪd","pos":"adj. 形容词","stars":4,"zh":"复杂且完善的","contextSenses":[0],"legacyId":"sophisticated|复杂且完善的","note":"常见义：精密的；复杂的；老练的；学习用法：sophisticated technology 先进复杂的技术；辨析：描述人可指老练有修养，不是本句义","examples":[{"en":"Around this time, writing became more sophisticated and allowed people to maintain records of the harvest and taxes.","zh":"大约在这一时期，文字变得更复杂完善，使人们可以保存收成和税收的记录。","sourceId":"C5","source":"original","number":14,"paragraph":"C"}],"para":"C","memory":{"method":"词族联想","parts":"sophisticated（复杂精密的）→ sophistication（复杂精密性）","tip":"本篇是社会和技术更复杂完善，不只是“时髦的”。","family":"sophistication 复杂精密性；sophisticated systems 复杂系统"}},{"id":"food-71ae371a85d4","term":"maintain","type":"word","ipa":"meɪnˈteɪn","pos":"v. 动词","stars":2,"zh":"保存，持续保有记录","contextSenses":[0],"legacyId":"maintain|保存，持续保有记录","note":"常见义：维持；维护；保养；学习用法：maintain records 保持记录；maintain standards 维持标准；辨析：maintain that… 还可指坚称","examples":[{"en":"Around this time, writing became more sophisticated and allowed people to maintain records of the harvest and taxes.","zh":"大约在这一时期，文字变得更复杂完善，使人们可以保存收成和税收的记录。","sourceId":"C5","source":"original","number":14,"paragraph":"C"}],"para":"C"},{"id":"food-845ae1788bab","term":"establish","type":"word","ipa":"ɪˈstæblɪʃ","pos":"v. 动词","stars":3,"zh":"建立","contextSenses":[0],"legacyId":"establish|建立","note":"常见义：设立；确立；学习用法：建立机构；establish a fact 确认事实；辨析：科学语境可以是证明，而不只是创办","examples":[{"en":"Eventually, formalized structures of government were established as people settled in one area.","zh":"最终，随着人们在一个地方定居，正式的政府组织结构建立起来。","sourceId":"C6","source":"original","number":15,"paragraph":"C"}],"para":"C"},{"id":"food-1ac203735bf6","term":"settle","type":"word","ipa":"ˈsetəl","pos":"v. 动词","stars":2,"zh":"定居","contextSenses":[0],"legacyId":"settle|定居","note":"常见义：安顿；定居；解决；学习用法：settle in 定居；settle a dispute 解决争议；辨析：本句不是解决一块区域","examples":[{"en":"Eventually, formalized structures of government were established as people settled in one area.","zh":"最终，随着人们在一个地方定居，正式的政府组织结构建立起来。","sourceId":"C6","source":"original","number":15,"paragraph":"C"}],"para":"C"},{"id":"food-64f4a7149b89","term":"immediately","type":"word","ipa":"ɪˈmiːdiətli","pos":"adv. 副词","stars":3,"zh":"立即，当时就","contextSenses":[0],"legacyId":"immediately|立即，当时就","note":"常见义：立刻；马上；学习用法：立即发生的影响；辨析：more than they could eat immediately 不等于永远吃不完","examples":[{"en":"The arrival of agriculture meant that, for the first time, our ancestors had more food than they could eat immediately.","zh":"农业的到来意味着，祖先们第一次拥有了超过当时能够立即吃完的食物。","sourceId":"D1","source":"original","number":16,"paragraph":"D"}],"para":"D"},{"id":"food-f596c9326f0f","term":"arrival","type":"word","ipa":"əˈraɪvəl","pos":"n. 名词","stars":2,"zh":"出现，到来","contextSenses":[0],"legacyId":"arrival|出现，到来","note":"常见义：抵达；到来；学习用法：新技术或时代到来；辨析：可以用于抽象事物 agriculture，不只是到站","examples":[{"en":"The arrival of agriculture meant that, for the first time, our ancestors had more food than they could eat immediately.","zh":"农业的到来意味着，祖先们第一次拥有了超过当时能够立即吃完的食物。","sourceId":"D1","source":"original","number":16,"paragraph":"D"}],"para":"D"},{"id":"food-588685046250","term":"seasonality","type":"word","ipa":"ˌsiːzəˈnæləti","pos":"n. 名词","stars":3,"zh":"季节性","contextSenses":[0],"legacyId":"seasonality|季节性","note":"常见义：随季节变化的特性；学习用法：seasonal variation 季节变化；辨析：不是天气本身，而是生产的周期性","examples":[{"en":"This, combined with the seasonality of production, led them to discover methods of preserving food: smoking, drying, adding acid by fermentation, or adding salt.","zh":"这一点，加上生产的季节性，促使他们发现了保存食物的方法：烟熏、干燥、通过发酵增加酸度，或加盐。","sourceId":"D2","source":"original","number":17,"paragraph":"D"}],"para":"D"},{"id":"food-d1a77a0371a8","term":"fermentation","type":"word","ipa":"ˌfɜːmenˈteɪʃən","pos":"n. 名词","stars":4,"zh":"发酵","contextSenses":[0],"legacyId":"fermentation|发酵","note":"常见义：发酵过程；学习用法：食品加工与保存；辨析：ferment 作动词为发酵，专业词以认读为主","examples":[{"en":"This, combined with the seasonality of production, led them to discover methods of preserving food: smoking, drying, adding acid by fermentation, or adding salt.","zh":"这一点，加上生产的季节性，促使他们发现了保存食物的方法：烟熏、干燥、通过发酵增加酸度，或加盐。","sourceId":"D2","source":"original","number":17,"paragraph":"D"}],"para":"D","memory":{"method":"派生构词","parts":"ferment（发酵）＋-ation","tip":"酵母让物质发生发酵；记过程名词 fermentation。","family":"ferment 发酵；fermented food 发酵食品"}},{"id":"food-e0d8c73123d9","term":"hostile","type":"word","ipa":"ˈhɒstaɪl","pos":"adj. 形容词","stars":3,"zh":"不利于细菌生存的","contextSenses":[0],"legacyId":"hostile|不利于细菌生存的","note":"常见义：敌对的；恶劣的；学习用法：hostile environment 恶劣环境；辨析：不是食物在对细菌怀有敌意","examples":[{"en":"These four methods all share one feature in common—they make the food a more hostile environment for bacteria that can cause it to spoil.","zh":"这四种方法有一个共同特点：它们使食物环境更不利于那些会令食物变质的细菌生存。","sourceId":"D3","source":"original","number":18,"paragraph":"D"}],"para":"D"},{"id":"food-0884a0cb9242","term":"spoil","type":"word","ipa":"spɔɪl","pos":"v. 动词","stars":2,"zh":"使食物变质","contextSenses":[0],"legacyId":"spoil|使食物变质","note":"常见义：破坏；变质；宠坏；学习用法：food spoils 食物变质；辨析：spoil a child 宠坏孩子；别混淆","examples":[{"en":"These four methods all share one feature in common—they make the food a more hostile environment for bacteria that can cause it to spoil.","zh":"这四种方法有一个共同特点：它们使食物环境更不利于那些会令食物变质的细菌生存。","sourceId":"D3","source":"original","number":18,"paragraph":"D"}],"para":"D"},{"id":"food-da7c1c58c0b6","term":"share in common","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"共有某种特征","contextSenses":[0],"legacyId":"share in common|共有某种特征","note":"常见义：共同拥有；学习用法：have a feature in common 有共同特点；辨析：学习输出宜简化成 share one feature 或 have one feature in common","examples":[{"en":"These four methods all share one feature in common—they make the food a more hostile environment for bacteria that can cause it to spoil.","zh":"这四种方法有一个共同特点：它们使食物环境更不利于那些会令食物变质的细菌生存。","sourceId":"D3","source":"original","number":18,"paragraph":"D"}],"para":"D"},{"id":"food-8314a73ad70b","term":"tend to","type":"phrase","ipa":"","pos":"短语／搭配","stars":4,"zh":"往往会，通常倾向于","contextSenses":[0],"legacyId":"tend to|往往会，通常倾向于","note":"常见义：倾向于；往往；学习用法：表达一般趋势；辨析：不是无例外的 always","examples":[{"en":"They also tend to slow down natural chemical reactions in the food that would cause decay.","zh":"这些方法也往往会减慢食物中可能导致腐败的自然化学反应。","sourceId":"D4","source":"original","number":19,"paragraph":"D"}],"para":"D"},{"id":"food-743802e97191","term":"decay","type":"word","ipa":"dɪˈkeɪ","pos":"v. 动词","stars":3,"zh":"腐败，腐烂","contextSenses":[0],"legacyId":"decay|腐败，腐烂","note":"常见义：腐朽；衰败；学习用法：食物腐败；城市或社会衰退；辨析：可用于抽象衰退，不仅是有机物腐烂","examples":[{"en":"They also tend to slow down natural chemical reactions in the food that would cause decay.","zh":"这些方法也往往会减慢食物中可能导致腐败的自然化学反应。","sourceId":"D4","source":"original","number":19,"paragraph":"D"}],"para":"D"},{"id":"food-6e26f8cd7ad3","term":"canning","type":"word","ipa":"ˈkænɪŋ","pos":"n. 名词","stars":3,"zh":"罐藏，将食物密封保存","contextSenses":[0],"legacyId":"canning|罐藏，将食物密封保存","note":"常见义：装罐保存；学习用法：食品工业中的罐藏技术；辨析：can 作名词为罐，不能当情态动词“能够”","examples":[{"en":"Although foods today are still preserved in these ancient ways, two more recent methods of preserving food have become more common: canning and freezing.","zh":"尽管今天食物仍按这些古老方式保存，但两种较新的保存方法已经更加普遍：罐藏和冷冻。","sourceId":"E1","source":"original","number":20,"paragraph":"E"}],"para":"E"},{"id":"food-678207cb47d1","term":"freezing","type":"word","ipa":"ˈfriːzɪŋ","pos":"adj.","stars":3,"zh":"冷冻","contextSenses":[0],"legacyId":"freezing|冷冻","note":"常见义：冻结；冷冻；学习用法：食品冷冻；freezing point 冰点；辨析：freezing 作形容词可指极冷的","examples":[{"en":"Although foods today are still preserved in these ancient ways, two more recent methods of preserving food have become more common: canning and freezing.","zh":"尽管今天食物仍按这些古老方式保存，但两种较新的保存方法已经更加普遍：罐藏和冷冻。","sourceId":"E1","source":"original","number":20,"paragraph":"E"}],"para":"E"},{"id":"food-7b6a65880d25","term":"invent","type":"word","ipa":"ɪnˈvent","pos":"v. 动词","stars":3,"zh":"发明","contextSenses":[0],"legacyId":"invent|发明","note":"常见义：创造此前没有的东西；学习用法：技术发明；invent a method 发明方法；辨析：不同于 discover 发现","examples":[{"en":"Canning was invented by a Frenchman, Nicolas Appert, in the early 19th century.","zh":"十九世纪初，一位名叫尼古拉 阿佩尔的法国人发明了罐藏技术。","sourceId":"E2","source":"original","number":21,"paragraph":"E"}],"para":"E"},{"id":"food-249218ba92f9","term":"early","type":"word","ipa":"ˈɜːli","pos":"adj. 形容词","stars":1,"zh":"世纪初","contextSenses":[0],"legacyId":"early|世纪初","note":"常见义：早的；初期的；学习用法：in the early 19th century 十九世纪初；辨析：不是十九岁，也不是十八世纪","examples":[{"en":"Canning was invented by a Frenchman, Nicolas Appert, in the early 19th century.","zh":"十九世纪初，一位名叫尼古拉 阿佩尔的法国人发明了罐藏技术。","sourceId":"E2","source":"original","number":21,"paragraph":"E"}],"para":"E"},{"id":"food-d7fd44d4bcc5","term":"seal","type":"word","ipa":"siːl","pos":"v. 动词","stars":2,"zh":"密封","contextSenses":[0],"legacyId":"seal|密封","note":"常见义：封住；盖章；海豹；学习用法：密封容器；seal an agreement 敲定协议；辨析：本句为动词，不是海豹","examples":[{"en":"He sealed food in bottles fabricated from glass and then heated them in boiling water to cook the contents.","zh":"他把食物密封在玻璃制成的瓶子里，然后把瓶子放到沸水中加热，煮熟里面的食物。","sourceId":"E3","source":"original","number":22,"paragraph":"E"}],"para":"E"},{"id":"food-99492de425c9","term":"fabricate","type":"word","ipa":"ˈfæbrɪkeɪt","pos":"v. 动词","stars":3,"zh":"制造玻璃容器","contextSenses":[0],"legacyId":"fabricate|制造玻璃容器","note":"常见义：制造；捏造；学习用法：制造部件；fabricate evidence 伪造证据；辨析：此处不含捏造或造假含义","examples":[{"en":"He sealed food in bottles fabricated from glass and then heated them in boiling water to cook the contents.","zh":"他把食物密封在玻璃制成的瓶子里，然后把瓶子放到沸水中加热，煮熟里面的食物。","sourceId":"E3","source":"original","number":22,"paragraph":"E"}],"para":"E"},{"id":"food-4a436180d2f0","term":"contents","type":"word","ipa":"ˈkɒntents","pos":"n. 名词","stars":2,"zh":"容器中的食物","contextSenses":[0],"legacyId":"contents|容器中的食物","note":"常见义：内容；所容纳的物品；学习用法：容器内物品；书的目录；辨析：复数 contents 本句不是满足的 content","examples":[{"en":"He sealed food in bottles fabricated from glass and then heated them in boiling water to cook the contents.","zh":"他把食物密封在玻璃制成的瓶子里，然后把瓶子放到沸水中加热，煮熟里面的食物。","sourceId":"E3","source":"original","number":22,"paragraph":"E"}],"para":"E"},{"id":"food-0fb2bca0b73c","term":"advantage over","type":"phrase","ipa":"","pos":"短语／搭配","stars":4,"zh":"相对于……的优势","contextSenses":[0],"legacyId":"advantage over|相对于……的优势","note":"常见义：优点；有利条件；学习用法：A has an advantage over B A优于B；辨析：over 在此不是空间上方","examples":[{"en":"Appert's method had great advantages over older methods of food preservation: it could be applied to a wide range of foods, and the flavor and texture were similar to freshly cooked products.","zh":"阿佩尔的方法比旧的食物保存方式有明显优势：它适用于多种食物，而且食物的风味和口感接近刚烹调好的产品。","sourceId":"E4","source":"original","number":23,"paragraph":"E"}],"para":"E"},{"id":"food-f77bd1495c55","term":"apply to","type":"phrase","ipa":"","pos":"短语／搭配","stars":4,"zh":"应用于","contextSenses":[0],"legacyId":"apply to|应用于","note":"常见义：运用；适用；学习用法：方法应用于某对象；辨析：apply for 是申请，不是本句","examples":[{"en":"Appert's method had great advantages over older methods of food preservation: it could be applied to a wide range of foods, and the flavor and texture were similar to freshly cooked products.","zh":"阿佩尔的方法比旧的食物保存方式有明显优势：它适用于多种食物，而且食物的风味和口感接近刚烹调好的产品。","sourceId":"E4","source":"original","number":23,"paragraph":"E"}],"para":"E"},{"id":"food-ce0bb66e25ed","term":"texture","type":"word","ipa":"ˈtekstʃə","pos":"n. 名词","stars":4,"zh":"口感所体现的质地","contextSenses":[0],"legacyId":"texture|口感所体现的质地","note":"常见义：质地；纹理；学习用法：食物口感；材料质感；辨析：不等于单纯味道 taste","examples":[{"en":"Appert's method had great advantages over older methods of food preservation: it could be applied to a wide range of foods, and the flavor and texture were similar to freshly cooked products.","zh":"阿佩尔的方法比旧的食物保存方式有明显优势：它适用于多种食物，而且食物的风味和口感接近刚烹调好的产品。","sourceId":"E4","source":"original","number":23,"paragraph":"E"}],"para":"E","memory":{"method":"语境联想","parts":"整体记 texture；以 food texture、fabric texture 联记","tip":"食物口感和布料质感都是纹理或质地；不是文本 text。","family":"textural 质地的；texture of food 食物质地"}},{"id":"food-004c09756841","term":"copy","type":"word","ipa":"ˈkɒpi","pos":"v. 动词","stars":2,"zh":"仿效，借鉴","contextSenses":[0],"legacyId":"copy|仿效，借鉴","note":"常见义：复制；抄写；模仿；学习用法：复制方法；一份副本；辨析：阅读中不必一律加上“抄袭”的贬义","examples":[{"en":"His idea was soon copied by an Englishman, Peter Durand.","zh":"他的构想很快被一位名叫彼得 杜兰德的英国人借鉴。","sourceId":"E5","source":"original","number":24,"paragraph":"E"}],"para":"E"},{"id":"food-ac5016272a66","term":"idea","type":"word","ipa":"aɪˈdɪə","pos":"n. 名词","stars":2,"zh":"构想","contextSenses":[0],"legacyId":"idea|构想","note":"常见义：想法；概念；学习用法：技术或方案构想；辨析：have no idea 表不知道，非“没有理想”","examples":[{"en":"His idea was soon copied by an Englishman, Peter Durand.","zh":"他的构想很快被一位名叫彼得 杜兰德的英国人借鉴。","sourceId":"E5","source":"original","number":24,"paragraph":"E"}],"para":"E"},{"id":"food-ebbeb9490233","term":"resistant to","type":"phrase","ipa":"","pos":"短语／搭配","stars":4,"zh":"能抵抗损坏的","contextSenses":[0],"legacyId":"resistant to|能抵抗损坏的","note":"常见义：抗……的；抵制……的；学习用法：resistant to damage/disease 耐损或抗病；辨析：to 为介词，后接名词","examples":[{"en":"Until this point, containers had been too heavy to be widely used, but Durand produced the first ones which were lightweight and resistant to damage.","zh":"此前，容器一直太重，难以广泛使用；但杜兰德生产出了第一批轻便且耐损坏的容器。","sourceId":"E6","source":"original","number":25,"paragraph":"E"}],"para":"E"},{"id":"food-6083de4b0b51","term":"lightweight","type":"word","ipa":"ˈlaɪtweɪt","pos":"adj. 形容词","stars":3,"zh":"轻便的","contextSenses":[0],"legacyId":"lightweight|轻便的","note":"常见义：重量轻的；学习用法：轻便材料或设备；辨析：作名词可指轻量级选手或无足轻重者，非本句","examples":[{"en":"Until this point, containers had been too heavy to be widely used, but Durand produced the first ones which were lightweight and resistant to damage.","zh":"此前，容器一直太重，难以广泛使用；但杜兰德生产出了第一批轻便且耐损坏的容器。","sourceId":"E6","source":"original","number":25,"paragraph":"E"}],"para":"E"},{"id":"food-f200c50711e5","term":"commercial","type":"word","ipa":"kəˈmɜːʃəl","pos":"adj. 形容词","stars":4,"zh":"商业化的","contextSenses":[0],"legacyId":"commercial|商业化的","note":"常见义：商业的；营利性的；学习用法：commercial production 商业生产；辨析：不是广告；commercial 作名词才可指商业广告","examples":[{"en":"Two years later, in 1812, two Englishmen, Bryan Donkin and John Hall, started the commercial canning of food, although the real rise in popularity of canning had to wait until the invention of the can opener in 1855.","zh":"两年后，也就是一八一二年，两位英国人布赖恩 唐金和约翰 霍尔开始商业化生产罐藏食品；不过，罐藏真正流行起来，要等到一八五五年开罐器发明之后。","sourceId":"E7","source":"original","number":26,"paragraph":"E"}],"para":"E","memory":{"method":"后缀构词","parts":"commerce（商业）→ commercial（商业的）","tip":"商业化规模的生产，与家庭自己保存食物区分。","family":"commerce 商业；commercially 商业上"}},{"id":"food-6bead612a50a","term":"popularity","type":"word","ipa":"ˌpɒpjəˈlærəti","pos":"n. 名词","stars":3,"zh":"受欢迎或普及程度","contextSenses":[0],"legacyId":"popularity|受欢迎或普及程度","note":"常见义：流行；受欢迎；学习用法：rise in popularity 日益流行；辨析：不等于人口 population","examples":[{"en":"Two years later, in 1812, two Englishmen, Bryan Donkin and John Hall, started the commercial canning of food, although the real rise in popularity of canning had to wait until the invention of the can opener in 1855.","zh":"两年后，也就是一八一二年，两位英国人布赖恩 唐金和约翰 霍尔开始商业化生产罐藏食品；不过，罐藏真正流行起来，要等到一八五五年开罐器发明之后。","sourceId":"E7","source":"original","number":26,"paragraph":"E"}],"para":"E"},{"id":"food-7a7f517f4d14","term":"chisel","type":"word","ipa":"ˈtʃɪzəl","pos":"n. 名词","stars":3,"zh":"凿子","contextSenses":[0],"legacyId":"chisel|凿子","note":"常见义：凿子；凿刻；学习用法：工具类识别词；辨析：低迁移专业词，认读即可","examples":[{"en":"Until then, cans were opened with a chisel and hammer.","zh":"在那之前，人们用凿子和锤子打开罐头。","sourceId":"E8","source":"original","number":27,"paragraph":"E"}],"para":"E"},{"id":"food-d885ba5f250b","term":"until then","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"在那之前","contextSenses":[0],"legacyId":"until then|在那之前","note":"常见义：直到那时；学习用法：连接前述历史时间节点；辨析：then 指1855年开罐器发明之前，不是1812年","examples":[{"en":"Until then, cans were opened with a chisel and hammer.","zh":"在那之前，人们用凿子和锤子打开罐头。","sourceId":"E8","source":"original","number":27,"paragraph":"E"}],"para":"E"},{"id":"food-aa5a349c3685","term":"date back to","type":"phrase","ipa":"","pos":"短语／搭配","stars":4,"zh":"可追溯到","contextSenses":[0],"legacyId":"date back to|可追溯到","note":"常见义：始于；可追溯至；学习用法：历史事物年代定位；辨析：主动结构，通常不说 be dated back to","examples":[{"en":"Canning is an extremely effective way of preserving food: one can containing meat, dating back to 1824, was opened in 1939, and the contents were still in good condition.","zh":"罐藏是一种极其有效的食物保存方法：一个装有肉、年代可追溯到一八二四年的罐头，在一九三九年被打开时，里面的食物仍保存良好。","sourceId":"E9","source":"original","number":28,"paragraph":"E"}],"para":"E"},{"id":"food-f17e6b449c02","term":"in good condition","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"保存状况良好","contextSenses":[0],"legacyId":"in good condition|保存状况良好","note":"常见义：处于良好状态；学习用法：设施或物品状态；辨析：condition 此处为状态，不是附带条件","examples":[{"en":"Canning is an extremely effective way of preserving food: one can containing meat, dating back to 1824, was opened in 1939, and the contents were still in good condition.","zh":"罐藏是一种极其有效的食物保存方法：一个装有肉、年代可追溯到一八二四年的罐头，在一九三九年被打开时，里面的食物仍保存良好。","sourceId":"E9","source":"original","number":28,"paragraph":"E"}],"para":"E"},{"id":"food-84cfc7ca7df1","term":"dominance","type":"word","ipa":"ˈdɒmɪnəns","pos":"n. 名词","stars":3,"zh":"主导地位","contextSenses":[0],"legacyId":"dominance|主导地位","note":"常见义：优势；支配地位；学习用法：market dominance 市场主导地位；辨析：dominance 不等于绝对垄断","examples":[{"en":"In the 21st century, the dominance of canning as a method of food preservation has been overtaken by freezing.","zh":"进入二十一世纪，冷冻已经取代罐藏，成为占主导地位的食物保存方式。","sourceId":"F1","source":"original","number":29,"paragraph":"F"}],"para":"F"},{"id":"food-6ae98a5ac26d","term":"overtake","type":"word","ipa":"ˌəʊvəˈteɪk","pos":"v. 动词","stars":4,"zh":"超过并取代其领先地位","contextSenses":[0],"legacyId":"overtake|超过并取代其领先地位","note":"常见义：赶上并超过；学习用法：需求或技术超过另一对象；辨析：be overtaken by 的 by 后是后来领先者","examples":[{"en":"In the 21st century, the dominance of canning as a method of food preservation has been overtaken by freezing.","zh":"进入二十一世纪，冷冻已经取代罐藏，成为占主导地位的食物保存方式。","sourceId":"F1","source":"original","number":29,"paragraph":"F"}],"para":"F","memory":{"method":"复合构词","parts":"over-（越过）＋take → overtake。","tip":"本篇表示一个年龄组的占比超过另一组；过去式 overtook，过去分词 overtaken。","family":"take—took—taken；overtake—overtook—overtaken"}},{"id":"food-b6ba852b60b8","term":"chill","type":"word","ipa":"tʃɪl","pos":"v. 动词","stars":2,"zh":"使食物冷却","contextSenses":[0],"legacyId":"chill|使食物冷却","note":"常见义：使变冷；寒意；学习用法：chilled food 冷藏食品；辨析：冷藏不必结冰，区别 freeze；chill out 为口语放松","examples":[{"en":"Chilling food to keep it fresh is an old idea.","zh":"用降温来保持食物新鲜，是一个古老的想法。","sourceId":"F2","source":"original","number":30,"paragraph":"F"}],"para":"F"},{"id":"food-704b32ef2f47","term":"fresh","type":"word","ipa":"freʃ","pos":"adj. 形容词","stars":2,"zh":"新鲜的","contextSenses":[0],"legacyId":"fresh|新鲜的","note":"常见义：新鲜的；新的；学习用法：fresh food 新鲜食物；fresh evidence 新证据；辨析：不总指刚烹饪好","examples":[{"en":"Chilling food to keep it fresh is an old idea.","zh":"用降温来保持食物新鲜，是一个古老的想法。","sourceId":"F2","source":"original","number":30,"paragraph":"F"}],"para":"F"},{"id":"food-fde9136d47c3","term":"mention","type":"word","ipa":"ˈmenʃən","pos":"v. 动词","stars":2,"zh":"记载，提及","contextSenses":[0],"legacyId":"mention|记载，提及","note":"常见义：提及；说到；学习用法：earliest mention 最早记载；辨析：名词 mention 不等于完整的历史证明","examples":[{"en":"The earliest mentions of icehouses, thick-walled buildings, half underground, date back to 1700 BC in northwest Iran.","zh":"最早关于冰窖的记载，可追溯到公元前一千七百年的伊朗西北部；冰窖是墙很厚、半埋在地下的建筑。","sourceId":"F3","source":"original","number":31,"paragraph":"F"}],"para":"F"},{"id":"food-ab372e913069","term":"underground","type":"word","ipa":"ˌʌndəˈɡraʊnd","pos":"adv. 副词","stars":3,"zh":"在地下","contextSenses":[0],"legacyId":"underground|在地下","note":"常见义：地下的；在地下；学习用法：地下设施；underground railway 地铁；辨析：可指秘密或非主流活动，非本句","examples":[{"en":"The earliest mentions of icehouses, thick-walled buildings, half underground, date back to 1700 BC in northwest Iran.","zh":"最早关于冰窖的记载，可追溯到公元前一千七百年的伊朗西北部；冰窖是墙很厚、半埋在地下的建筑。","sourceId":"F3","source":"original","number":31,"paragraph":"F"}],"para":"F"},{"id":"food-53f749c2ca5d","term":"lower","type":"word","ipa":"ˈləʊə","pos":"v. 动词","stars":2,"zh":"降低","contextSenses":[0],"legacyId":"lower|降低","note":"常见义：使下降；较低的；学习用法：lower costs/temperature 降低费用或温度；辨析：作动词，不是形容词修饰 freezing point","examples":[{"en":"In early 16th-century Italy, water was mixed with chemicals to lower its freezing point to -18 degrees Celsius.","zh":"十六世纪初的意大利，人们把水与化学物质混合，将水的冰点降低到零下十八摄氏度。","sourceId":"F4","source":"original","number":32,"paragraph":"F"}],"para":"F"},{"id":"food-2dec39b80c65","term":"freezing point","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"冰点","contextSenses":[0],"legacyId":"freezing point|冰点","note":"常见义：物质凝固的温度；学习用法：科学阅读或听力中的温度指标；辨析：point 此处为临界数值，不是观点","examples":[{"en":"In early 16th-century Italy, water was mixed with chemicals to lower its freezing point to -18 degrees Celsius.","zh":"十六世纪初的意大利，人们把水与化学物质混合，将水的冰点降低到零下十八摄氏度。","sourceId":"F4","source":"original","number":32,"paragraph":"F"}],"para":"F"},{"id":"food-fddab260ab0d","term":"transport","type":"word","ipa":"trænsˈpɔːt","pos":"v. 动词","stars":3,"zh":"运输","contextSenses":[0],"legacyId":"transport|运输","note":"常见义：运送；交通运输；学习用法：transport goods 运输货物；辨析：名词指运输系统或方式；动词指运送","examples":[{"en":"Several centuries later, frozen fish and other goods were transported by ship from Australia to England.","zh":"几个世纪后，冷冻鱼和其他货物从澳大利亚经海运运往英国。","sourceId":"F5","source":"original","number":33,"paragraph":"F"}],"para":"F"},{"id":"food-8ee3fc070264","term":"goods","type":"word","ipa":"ɡʊdz","pos":"n. 名词","stars":2,"zh":"货物","contextSenses":[0],"legacyId":"goods|货物","note":"常见义：商品；货物；学习用法：goods and services 商品与服务；辨析：通常用复数，与 good 好的不是同一用法","examples":[{"en":"Several centuries later, frozen fish and other goods were transported by ship from Australia to England.","zh":"几个世纪后，冷冻鱼和其他货物从澳大利亚经海运运往英国。","sourceId":"F5","source":"original","number":33,"paragraph":"F"}],"para":"F"},{"id":"food-53e20ccaed4f","term":"industry","type":"word","ipa":"ˈɪndəstri","pos":"n. 名词","stars":2,"zh":"产业","contextSenses":[0],"legacyId":"industry|产业","note":"常见义：工业；行业；学习用法：food industry 食品产业；辨析：不能自动等同于某一家工厂","examples":[{"en":"However, the modern frozen food industry was started in the 1920s by an American, Clarence Birdseye.","zh":"然而，现代冷冻食品产业是在二十世纪二十年代由一位美国人克拉伦斯 伯兹艾开创的。","sourceId":"F6","source":"original","number":34,"paragraph":"F"}],"para":"F"},{"id":"food-0fbc2510ffeb","term":"start","type":"word","ipa":"stɑːt","pos":"v. 动词","stars":1,"zh":"开创，建立","contextSenses":[0],"legacyId":"start|开创，建立","note":"常见义：开始；启动；学习用法：start an industry/business 开创行业或企业；辨析：此处是被动，说明创始者","examples":[{"en":"However, the modern frozen food industry was started in the 1920s by an American, Clarence Birdseye.","zh":"然而，现代冷冻食品产业是在二十世纪二十年代由一位美国人克拉伦斯 伯兹艾开创的。","sourceId":"F6","source":"original","number":34,"paragraph":"F"}],"para":"F"},{"id":"food-a7ded5069428","term":"observe","type":"word","ipa":"əbˈzɜːv","pos":"v. 动词","stars":2,"zh":"观察到某一现象","contextSenses":[0],"legacyId":"observe|观察到某一现象","note":"常见义：观察；遵守；评论；学习用法：observe a pattern 观察规律；observe rules 遵守规则；辨析：不是 always“看”；遵守规则是常见另一义","examples":[{"en":"While on a fishing trip with the Inuit in the Canadian Arctic, Birdseye observed that rapid freezing creates smaller ice crystals and therefore causes less damage to food—a discovery he had not expected.","zh":"伯兹艾在加拿大北极地区与因纽特人捕鱼时，观察到快速冷冻会形成较小的冰晶，因此对食物造成的损伤较小；这一发现是他此前没有预料到的。","sourceId":"F7","source":"original","number":35,"paragraph":"F"}],"para":"F"},{"id":"food-6ffc1d6161be","term":"rapid","type":"word","ipa":"ˈræpɪd","pos":"adj. 形容词","stars":2,"zh":"快速的","contextSenses":[0],"legacyId":"rapid|快速的","note":"常见义：迅速的；学习用法：rapid growth/freezing 快速增长或冷冻；辨析：近义 fast，阅读中可替换","examples":[{"en":"While on a fishing trip with the Inuit in the Canadian Arctic, Birdseye observed that rapid freezing creates smaller ice crystals and therefore causes less damage to food—a discovery he had not expected.","zh":"伯兹艾在加拿大北极地区与因纽特人捕鱼时，观察到快速冷冻会形成较小的冰晶，因此对食物造成的损伤较小；这一发现是他此前没有预料到的。","sourceId":"F7","source":"original","number":35,"paragraph":"F"}],"para":"F"},{"id":"food-5a8cea3170ed","term":"expect","type":"word","ipa":"ɪkˈspekt","pos":"v. 动词","stars":3,"zh":"预料这一发现","contextSenses":[0],"legacyId":"expect|预料这一发现","note":"常见义：预期；期望；学习用法：unexpected 未预料的；expect a result 预期结果；辨析：had not expected 与 already believed 意义相反","examples":[{"en":"While on a fishing trip with the Inuit in the Canadian Arctic, Birdseye observed that rapid freezing creates smaller ice crystals and therefore causes less damage to food—a discovery he had not expected.","zh":"伯兹艾在加拿大北极地区与因纽特人捕鱼时，观察到快速冷冻会形成较小的冰晶，因此对食物造成的损伤较小；这一发现是他此前没有预料到的。","sourceId":"F7","source":"original","number":35,"paragraph":"F"}],"para":"F"},{"id":"food-3c15b2fc1a09","term":"nevertheless","type":"word","ipa":"ˌnevəðəˈles","pos":"adv.","stars":3,"zh":"尽管如此","contextSenses":[0],"legacyId":"nevertheless|尽管如此","note":"常见义：然而；仍然；学习用法：承接上文并引出限制或转折；辨析：不是因为；不能当因果词","examples":[{"en":"Nevertheless, the major growth in demand for frozen food came with the arrival of freezers in ordinary people's homes.","zh":"尽管如此，冷冻食品需求真正的大幅增长，是在冰柜进入普通家庭后才出现的。","sourceId":"F8","source":"original","number":36,"paragraph":"F"}],"para":"F"},{"id":"food-c6fa1355489f","term":"demand","type":"word","ipa":"dɪˈmɑːnd","pos":"n. 名词","stars":2,"zh":"需求","contextSenses":[0],"legacyId":"demand|需求","note":"常见义：需求；要求；学习用法：demand for products 对产品的需求；辨析：经济语境是需求，不是强硬命令","examples":[{"en":"Nevertheless, the major growth in demand for frozen food came with the arrival of freezers in ordinary people's homes.","zh":"尽管如此，冷冻食品需求真正的大幅增长，是在冰柜进入普通家庭后才出现的。","sourceId":"F8","source":"original","number":36,"paragraph":"F"}],"para":"F"},{"id":"food-f856e352c3b1","term":"consistency","type":"word","ipa":"kənˈsɪstənsi","pos":"n. 名词","stars":4,"zh":"质地，稠度或口感状态","contextSenses":[0],"legacyId":"consistency|质地，稠度或口感状态","note":"常见义：一致性；稠度；连贯性；学习用法：食物稠度；观点或结果一致性；辨析：此处不是“口味一致的态度”，而是食物物理质地","examples":[{"en":"The advantages of frozen over canned food include the fact that the flavor and consistency are often identical to the fresh product, and freezing can be used to preserve a wide variety of foods.","zh":"与罐藏食品相比，冷冻食品的优势包括：风味和质地往往与新鲜食品完全相同，而且冷冻可以保存种类繁多的食物。","sourceId":"F9","source":"original","number":37,"paragraph":"F"}],"para":"F","memory":{"method":"词族变化","parts":"consistent（一致的）→ consistency（一致性、稠度）","tip":"本篇结合食物理解为质地或稠度，不能只记“一致性”。","family":"consistent 一致的；a thick consistency 浓稠质地"}},{"id":"food-73a54c0aa0b3","term":"identical to","type":"phrase","ipa":"","pos":"短语／搭配","stars":4,"zh":"与……完全相同","contextSenses":[0],"legacyId":"identical to|与……完全相同","note":"常见义：完全相同的；学习用法：identical results 相同结果；辨析：比 similar to 程度强，但原文 often 限定频率","examples":[{"en":"The advantages of frozen over canned food include the fact that the flavor and consistency are often identical to the fresh product, and freezing can be used to preserve a wide variety of foods.","zh":"与罐藏食品相比，冷冻食品的优势包括：风味和质地往往与新鲜食品完全相同，而且冷冻可以保存种类繁多的食物。","sourceId":"F9","source":"original","number":37,"paragraph":"F"}],"para":"F"},{"id":"food-62941a820361","term":"variety","type":"word","ipa":"vəˈraɪəti","pos":"n. 名词","stars":2,"zh":"多种类别","contextSenses":[0],"legacyId":"variety|多种类别","note":"常见义：种类；多样性；学习用法：a wide variety of 多种多样；辨析：variety 可指某个品种，不总是整体多样性","examples":[{"en":"The advantages of frozen over canned food include the fact that the flavor and consistency are often identical to the fresh product, and freezing can be used to preserve a wide variety of foods.","zh":"与罐藏食品相比，冷冻食品的优势包括：风味和质地往往与新鲜食品完全相同，而且冷冻可以保存种类繁多的食物。","sourceId":"F9","source":"original","number":37,"paragraph":"F"}],"para":"F"},{"id":"food-5cc6c8459548","term":"preserve food","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"保存食物","contextSenses":[0],"note":"说明保存手段；preserve后接保存对象。 由原句提炼或迁移；具体例句与原文形式可能不同。","para":"A","examples":[{"en":"During the journey from our hunter-gatherer ancestors to the present day, there have been three seismic changes that have impacted the food we eat: the discovery of cooking, the emergence of agriculture, and the invention of methods of preserving food.","zh":"从狩猎采集的祖先走到今天，人类经历了三次深刻影响所吃食物的重大变化：发现烹饪、农业出现，以及发明保存食物的方法。","sourceId":"A1","source":"original","number":1,"paragraph":"A"},{"en":"People use freezing to preserve food.","zh":"人们用冷冻保存食物。","added":true,"source":"supplemental","number":null}]},{"id":"food-97be6626cf22","term":"with the advent of","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"随着……出现","contextSenses":[0],"note":"用于重要技术或社会事物的出现，通常不描述普通到访。 由原句提炼或迁移；具体例句与原文形式可能不同。","para":"C","examples":[{"en":"This all began to change around 10,500 years ago with the advent of farming, which led to dramatic changes in human societies.","zh":"大约一万零五百年前，随着农业的出现，这一切开始改变，并由此引发了人类社会的重大变化。","sourceId":"C2","source":"original","number":11,"paragraph":"C"},{"en":"With the advent of smartphones, communication became more convenient.","zh":"随着智能手机出现，沟通更便捷。","added":true,"source":"supplemental","number":null}]},{"id":"food-46f5b39a09bf","term":"resistant to damage","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"耐损坏","contextSenses":[0],"note":"描述材料或容器；to后接名词。 由原句提炼或迁移；具体例句与原文形式可能不同。","para":"E","examples":[{"en":"Until this point, containers had been too heavy to be widely used, but Durand produced the first ones which were lightweight and resistant to damage.","zh":"此前，容器一直太重，难以广泛使用；但杜兰德生产出了第一批轻便且耐损坏的容器。","sourceId":"E6","source":"original","number":25,"paragraph":"E"},{"en":"These containers are resistant to damage.","zh":"这些容器耐损坏。","added":true,"source":"supplemental","number":null}]},{"id":"food-b4a9cfe8beff","term":"the advantages of A over B","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"A比B的优势","contextSenses":[0],"note":"of后先写优势方，over后写比较对象。 由原句提炼或迁移；具体例句与原文形式可能不同。","para":"F","examples":[{"en":"The advantages of frozen over canned food include the fact that the flavor and consistency are often identical to the fresh product, and freezing can be used to preserve a wide variety of foods.","zh":"与罐藏食品相比，冷冻食品的优势包括：风味和质地往往与新鲜食品完全相同，而且冷冻可以保存种类繁多的食物。","sourceId":"F9","source":"original","number":37,"paragraph":"F"},{"en":"The advantages of frozen food over canned food include its texture.","zh":"冷冻食品相比罐藏食品的优势包括质地。","added":true,"source":"supplemental","number":null}]}],"sentences":[{"id":"food-A1","sourceId":"A1","en":"During the journey from our hunter-gatherer ancestors to the present day, there have been three seismic changes that have impacted the food we eat: the discovery of cooking, the emergence of agriculture, and the invention of methods of preserving food.","zh":"从狩猎采集的祖先走到今天，人类经历了三次深刻影响所吃食物的重大变化：发现烹饪、农业出现，以及发明保存食物的方法。","para":"A","note":"核心句式：There have been three changes that have impacted…，there be 的现在完成时强调迄今的变化；that 修饰 changes。冒号后列出全文的三个主题。the food we eat 中 we eat 是省略关系词的定语从句。","paragraph":"A"},{"id":"food-A2","sourceId":"A2","en":"The 19th-century scientist Charles Darwin thought that cooking, after language, was the greatest discovery made by man.","zh":"十九世纪科学家查尔斯 达尔文认为，烹饪是人类仅次于语言的最伟大发现。","para":"A","note":"thought that… 是宾语从句；made by man 修饰 discovery。after language 是插入的排序限定，不要漏译。man 在此泛指人类。","paragraph":"A"},{"id":"food-A3","sourceId":"A3","en":"All of us eat some raw food, such as fruit and vegetables, but the great majority of food we consume is cooked.","zh":"我们每个人都吃一些生食，例如水果和蔬菜，但我们所吃食物的绝大部分是熟食。","para":"A","note":"the great majority of… 表绝大多数，仍允许少量例外；不是全部食物都被烹饪。food we consume 的 consume 与 eat 构成替换。","paragraph":"A"},{"id":"food-A4","sourceId":"A4","en":"Cooking can turn plants that are inedible into edible food by destroying toxic chemicals that plants often manufacture to protect themselves against attack by insects or other herbivorous animals.","zh":"烹饪可以破坏植物常常制造、用来抵御昆虫或其他食草动物攻击的有毒化学物质，从而把不可食用的植物变成可食用的食物。","para":"A","note":"长句拆解：Cooking can turn plants into edible food 是主干；第一个 that are inedible 修饰 plants；by destroying… 表实现方式；第二个 that plants often manufacture 修饰 toxic chemicals；to protect themselves… 表植物产生毒素的目的，themselves 指 plants。读成“烹饪破坏毒素→植物可食用”，别错认成烹饪制造毒素。","paragraph":"A"},{"id":"food-A5","sourceId":"A5","en":"These toxic chemicals are referred to as “plant secondary compounds” because they are not directly involved in the plant's normal growth, development, and reproduction, and are produced purely as chemical defenses.","zh":"这些有毒化学物质被称为植物次生化合物，因为它们不直接参与植物的正常生长、发育与繁殖，而完全是作为化学防御物质产生的。","para":"A","note":"because 引导原因；they are not… and are produced… 共用主语。secondary 在这里是生物化学分类“次生”，不是说明毒素不重要。","paragraph":"A"},{"id":"food-A6","sourceId":"A6","en":"They give many of the plants we consume, such as coffee or Brussels sprouts, their bitter taste.","zh":"它们使我们食用的许多植物，例如咖啡或抱子甘蓝，带有苦味。","para":"A","note":"They 指有毒化学物质。give [many of the plants we consume] [their bitter taste] 为双宾语结构，中间插入举例使宾语被拉长。","paragraph":"A"},{"id":"food-B1","sourceId":"B1","en":"Cooked food is often more digestible because heat breaks down tough cellulose cell walls in plants or tough connective tissue in animals.","zh":"熟食往往更容易消化，因为加热会分解植物中坚韧的纤维素细胞壁，或动物中坚韧的结缔组织。","para":"B","note":"because 后解释原因。tough 在本句指韧、难咀嚼，不是“厉害的人”。often 保留频率限定。","paragraph":"B"},{"id":"food-B2","sourceId":"B2","en":"Chewing raw turnip, a plate of uncooked rice, or a raw leg of lamb is much harder work than eating the cooked equivalent.","zh":"咀嚼生芜菁、一盘未煮熟的米饭或一只生羊腿，比吃相应的熟食费力得多。","para":"B","note":"主干 Chewing… is much harder work than eating…；两个动名词短语分别构成主语和比较对象。much 加强比较级，不是 many harder。","paragraph":"B"},{"id":"food-B3","sourceId":"B3","en":"The energy expended in chewing to break down the tough material is replaced by energy from the fuel used in cooking the food, so the ratio of energy gained to energy expended by the body is greater when food is cooked.","zh":"原本通过咀嚼来分解坚韧材料所消耗的能量，改由烹饪时使用的燃料所提供的能量承担；因此，食物煮熟后，身体获得的能量与自身消耗的能量之比更高。","para":"B","note":"重点拆解：① The energy [expended in chewing to break down…] is replaced by energy [from the fuel used in cooking…]。先去掉修饰，读“咀嚼消耗的能量改由烹饪燃料提供”。② so 引出结论：the ratio… is greater。③ gained 修饰第一个 energy；expended by the body 修饰第二个 energy。只比较身体自身的能量收益与支出，不能据此推出整个烹饪系统完全不耗能。","paragraph":"B"},{"id":"food-C1","sourceId":"C1","en":"Until the development of agriculture, hunter-gatherers spent up to seven hours a day gathering food.","zh":"农业出现以前，狩猎采集者每天最多要花七个小时获取食物。","para":"C","note":"spend + 时间 + doing 为核心句式：spent up to seven hours a day gathering food。Until… 表截至农业发展前的时期。","paragraph":"C"},{"id":"food-C2","sourceId":"C2","en":"This all began to change around 10,500 years ago with the advent of farming, which led to dramatic changes in human societies.","zh":"大约一万零五百年前，随着农业的出现，这一切开始改变，并由此引发了人类社会的重大变化。","para":"C","note":"which 指农业出现这一发展，并引出社会变化；around 标记近似年代。文章给出的历史时间用于阅读定位，不把各项变化误当成同一年同时完成。","paragraph":"C"},{"id":"food-C3","sourceId":"C3","en":"People began to create a variety of new tools to aid survival, and in turn, populations increased in size.","zh":"人们开始创造多种新工具来帮助生存，人口规模也随之增加。","para":"C","note":"to aid survival 表目的；in turn 连接因果链“工具发展→生存条件变化→人口增加”。","paragraph":"C"},{"id":"food-C4","sourceId":"C4","en":"These changes led to the possibility of specialization of different tasks within society.","zh":"这些变化使社会内部不同任务的专业分工成为可能。","para":"C","note":"led to the possibility of… 表创造可能性，不是宣称所有社会都立即完成分工。","paragraph":"C"},{"id":"food-C5","sourceId":"C5","en":"Around this time, writing became more sophisticated and allowed people to maintain records of the harvest and taxes.","zh":"大约在这一时期，文字变得更复杂完善，使人们可以保存收成和税收的记录。","para":"C","note":"writing 在这里是文字及书写体系，不是个人作文水平。allow sb to do sth 为允许或使某人能够做某事。","paragraph":"C"},{"id":"food-C6","sourceId":"C6","en":"Eventually, formalized structures of government were established as people settled in one area.","zh":"最终，随着人们在一个地方定居，正式的政府组织结构建立起来。","para":"C","note":"as 引出伴随发展的时间背景；were established 为被动。formalized 指制度化、正式化。","paragraph":"C"},{"id":"food-D1","sourceId":"D1","en":"The arrival of agriculture meant that, for the first time, our ancestors had more food than they could eat immediately.","zh":"农业的到来意味着，祖先们第一次拥有了超过当时能够立即吃完的食物。","para":"D","note":"had more food than they could eat… 为比较结构；that 引导 meant 的宾语从句，for the first time 为插入时间限定。","paragraph":"D"},{"id":"food-D2","sourceId":"D2","en":"This, combined with the seasonality of production, led them to discover methods of preserving food: smoking, drying, adding acid by fermentation, or adding salt.","zh":"这一点，加上生产的季节性，促使他们发现了保存食物的方法：烟熏、干燥、通过发酵增加酸度，或加盐。","para":"D","note":"This 指食物盈余；combined with… 是过去分词短语补充另一因素，不能当第二个独立谓语。led them to discover… 为“促使某人做”。","paragraph":"D"},{"id":"food-D3","sourceId":"D3","en":"These four methods all share one feature in common—they make the food a more hostile environment for bacteria that can cause it to spoil.","zh":"这四种方法有一个共同特点：它们使食物环境更不利于那些会令食物变质的细菌生存。","para":"D","note":"make + 宾语 + 名词补语：make the food a more hostile environment。that can cause it to spoil 修饰 bacteria；it 指 food。","paragraph":"D"},{"id":"food-D4","sourceId":"D4","en":"They also tend to slow down natural chemical reactions in the food that would cause decay.","zh":"这些方法也往往会减慢食物中可能导致腐败的自然化学反应。","para":"D","note":"that would cause decay 修饰 chemical reactions；They 指四种保存方法。slow down 与 retard/reduce the rate of 可形成理解层面的替换。","paragraph":"D"},{"id":"food-E1","sourceId":"E1","en":"Although foods today are still preserved in these ancient ways, two more recent methods of preserving food have become more common: canning and freezing.","zh":"尽管今天食物仍按这些古老方式保存，但两种较新的保存方法已经更加普遍：罐藏和冷冻。","para":"E","note":"Although 从句承认传统方法仍存在；主句介绍新方法。more recent 不等于刚刚发明，比较对象为古老方法。","paragraph":"E"},{"id":"food-E2","sourceId":"E2","en":"Canning was invented by a Frenchman, Nicolas Appert, in the early 19th century.","zh":"十九世纪初，一位名叫尼古拉 阿佩尔的法国人发明了罐藏技术。","para":"E","note":"was invented by… 适合流程或历史写作。a Frenchman 与 Nicolas Appert 为同位关系。","paragraph":"E"},{"id":"food-E3","sourceId":"E3","en":"He sealed food in bottles fabricated from glass and then heated them in boiling water to cook the contents.","zh":"他把食物密封在玻璃制成的瓶子里，然后把瓶子放到沸水中加热，煮熟里面的食物。","para":"E","note":"bottles fabricated from glass＝bottles which were fabricated from glass。heated them 的 them 指 bottles，不是 food；to cook… 表目的。","paragraph":"E"},{"id":"food-E4","sourceId":"E4","en":"Appert's method had great advantages over older methods of food preservation: it could be applied to a wide range of foods, and the flavor and texture were similar to freshly cooked products.","zh":"阿佩尔的方法比旧的食物保存方式有明显优势：它适用于多种食物，而且食物的风味和口感接近刚烹调好的产品。","para":"E","note":"it 指 method；flavor and texture 作并列主语。similar to 是相似，不是完全一致，做判断题要保留程度。","paragraph":"E"},{"id":"food-E5","sourceId":"E5","en":"His idea was soon copied by an Englishman, Peter Durand.","zh":"他的构想很快被一位名叫彼得 杜兰德的英国人借鉴。","para":"E","note":"His 指 Appert；was copied by 的动作执行者是 Durand，人物不能互换。","paragraph":"E"},{"id":"food-E6","sourceId":"E6","en":"Until this point, containers had been too heavy to be widely used, but Durand produced the first ones which were lightweight and resistant to damage.","zh":"此前，容器一直太重，难以广泛使用；但杜兰德生产出了第一批轻便且耐损坏的容器。","para":"E","note":"核心句式：too + 形容词 + to do，太……以至于不能……；to be widely used 为被动不定式。ones 代替 containers；which 修饰 ones。had been 回顾改进前的状态。","paragraph":"E"},{"id":"food-E7","sourceId":"E7","en":"Two years later, in 1812, two Englishmen, Bryan Donkin and John Hall, started the commercial canning of food, although the real rise in popularity of canning had to wait until the invention of the can opener in 1855.","zh":"两年后，也就是一八一二年，两位英国人布赖恩 唐金和约翰 霍尔开始商业化生产罐藏食品；不过，罐藏真正流行起来，要等到一八五五年开罐器发明之后。","para":"E","note":"主句 started…；although 后让步句解释普及受工具限制。had to wait until… 指实际发展推迟到某节点；1812为商业化，1855为开罐器，不能混成同一事件。","paragraph":"E"},{"id":"food-E8","sourceId":"E8","en":"Until then, cans were opened with a chisel and hammer.","zh":"在那之前，人们用凿子和锤子打开罐头。","para":"E","note":"with a chisel and hammer 表工具；cans were opened 是被动流程表达。","paragraph":"E"},{"id":"food-E9","sourceId":"E9","en":"Canning is an extremely effective way of preserving food: one can containing meat, dating back to 1824, was opened in 1939, and the contents were still in good condition.","zh":"罐藏是一种极其有效的食物保存方法：一个装有肉、年代可追溯到一八二四年的罐头，在一九三九年被打开时，里面的食物仍保存良好。","para":"E","note":"主干 one can… was opened… and the contents were…；containing meat 和 dating back to 1824 都修饰 can。这个例子证实有效性，不能推出所有罐头都能保存同样久。","paragraph":"E"},{"id":"food-F1","sourceId":"F1","en":"In the 21st century, the dominance of canning as a method of food preservation has been overtaken by freezing.","zh":"进入二十一世纪，冷冻已经取代罐藏，成为占主导地位的食物保存方式。","para":"F","note":"has been overtaken by freezing 为现在完成时被动。不是“罐藏超过冷冻”，也不意味着罐藏消失。","paragraph":"F"},{"id":"food-F2","sourceId":"F2","en":"Chilling food to keep it fresh is an old idea.","zh":"用降温来保持食物新鲜，是一个古老的想法。","para":"F","note":"Chilling food… 为动名词主语；to keep it fresh 表目的，it 指 food。keep + 宾语 + 形容词 为常用结构。","paragraph":"F"},{"id":"food-F3","sourceId":"F3","en":"The earliest mentions of icehouses, thick-walled buildings, half underground, date back to 1700 BC in northwest Iran.","zh":"最早关于冰窖的记载，可追溯到公元前一千七百年的伊朗西北部；冰窖是墙很厚、半埋在地下的建筑。","para":"F","note":"主干 The earliest mentions… date back to…；thick-walled buildings 为 icehouses 的同位解释，half underground 再补充位置。BC 指公元前。","paragraph":"F"},{"id":"food-F4","sourceId":"F4","en":"In early 16th-century Italy, water was mixed with chemicals to lower its freezing point to -18 degrees Celsius.","zh":"十六世纪初的意大利，人们把水与化学物质混合，将水的冰点降低到零下十八摄氏度。","para":"F","note":"was mixed with… 为被动；to lower… 表目的。阅读按原文理解，不据此推成任何普通水加化学品都能达到同一结果。","paragraph":"F"},{"id":"food-F5","sourceId":"F5","en":"Several centuries later, frozen fish and other goods were transported by ship from Australia to England.","zh":"几个世纪后，冷冻鱼和其他货物从澳大利亚经海运运往英国。","para":"F","note":"from Australia to England 为运输方向。句子没有提到 Birdseye 在澳大利亚任职，不能把邻近的历史背景当作个人履历。","paragraph":"F"},{"id":"food-F6","sourceId":"F6","en":"However, the modern frozen food industry was started in the 1920s by an American, Clarence Birdseye.","zh":"然而，现代冷冻食品产业是在二十世纪二十年代由一位美国人克拉伦斯 伯兹艾开创的。","para":"F","note":"However 引出古老降温手段与现代产业之间的转折。American 是国籍，不能据此判断他之前在哪些国家工作。","paragraph":"F"},{"id":"food-F7","sourceId":"F7","en":"While on a fishing trip with the Inuit in the Canadian Arctic, Birdseye observed that rapid freezing creates smaller ice crystals and therefore causes less damage to food—a discovery he had not expected.","zh":"伯兹艾在加拿大北极地区与因纽特人捕鱼时，观察到快速冷冻会形成较小的冰晶，因此对食物造成的损伤较小；这一发现是他此前没有预料到的。","para":"F","note":"重点拆解：While on a fishing trip… 省略 he was，逻辑主语是 Birdseye。observed that 后有并列谓语 creates smaller ice crystals 和 causes less damage。therefore 标记因果。破折号后 a discovery… 概括前面观察结果，he had not expected 是省略 that 的定语从句。它明确否定“证实早已相信的看法”，是错题关键。","paragraph":"F"},{"id":"food-F8","sourceId":"F8","en":"Nevertheless, the major growth in demand for frozen food came with the arrival of freezers in ordinary people's homes.","zh":"尽管如此，冷冻食品需求真正的大幅增长，是在冰柜进入普通家庭后才出现的。","para":"F","note":"the major growth… came with… 表需求增长与家用冰柜出现相关。速冻发现是技术基础，家庭冰柜是大规模需求增长的推动因素，二者别混同。","paragraph":"F"},{"id":"food-F9","sourceId":"F9","en":"The advantages of frozen over canned food include the fact that the flavor and consistency are often identical to the fresh product, and freezing can be used to preserve a wide variety of foods.","zh":"与罐藏食品相比，冷冻食品的优势包括：风味和质地往往与新鲜食品完全相同，而且冷冻可以保存种类繁多的食物。","para":"F","note":"主干 The advantages… include the fact that…；that 引出两项并列内容：flavor and consistency are… 与 freezing can be used…。often 使“完全相同”成为通常现象，不是绝对保证。用于写作可学 The advantages of A over B include…。","paragraph":"F"}],"examples":[{"en":"People use freezing to preserve food.","zh":"人们用冷冻保存食物。","added":true},{"en":"We freeze vegetables to preserve them for longer.","zh":"我们冷冻蔬菜以保存更久。","added":true},{"en":"Salt has long been used to preserve food.","zh":"盐长期用于保存食物。","added":true},{"en":"Preserving food properly can reduce waste.","zh":"妥善保存食物可以减少浪费。","added":true},{"en":"Heat breaks down some tough materials in food.","zh":"热量会分解食物中的一些坚韧材料。","added":true},{"en":"Enzymes help break down food in the body.","zh":"酶帮助身体分解食物。","added":true},{"en":"The material is broken down into smaller pieces.","zh":"这种材料被分解为较小块。","added":true},{"en":"I break down large tasks into smaller steps.","zh":"我把大任务拆成小步骤。","added":true},{"en":"With the advent of smartphones, communication became more convenient.","zh":"随着智能手机出现，沟通更便捷。","added":true},{"en":"With the advent of online learning, students gained more flexibility.","zh":"随着在线学习出现，学生有了更多灵活性。","added":true},{"en":"With the advent of digital payments, cash became less necessary.","zh":"随着数字支付出现，现金的必要性降低。","added":true},{"en":"With the advent of farming, people began to settle in one place.","zh":"随着农业出现，人们开始定居。","added":true},{"en":"Better storage can lead to less food waste.","zh":"更好的储存可减少食物浪费。","added":true},{"en":"Regular practice can lead to greater confidence.","zh":"经常练习可提升信心。","added":true},{"en":"Habitat loss can lead to population decline.","zh":"栖息地丧失可导致种群下降。","added":true},{"en":"Poor planning can lead to unnecessary delays.","zh":"规划不当可导致不必要的延误。","added":true},{"en":"These containers are resistant to damage.","zh":"这些容器耐损坏。","added":true},{"en":"This suitcase is lightweight and resistant to damage.","zh":"这个行李箱轻便且耐损坏。","added":true},{"en":"The new packaging is resistant to damage during transport.","zh":"新包装在运输中耐损坏。","added":true},{"en":"The protective case is designed to be resistant to damage.","zh":"保护壳被设计为耐损坏。","added":true},{"en":"The advantages of frozen food over canned food include its texture.","zh":"冷冻食品相比罐藏食品的优势包括质地。","added":true},{"en":"The advantages of cycling over driving include lower costs.","zh":"骑车相比开车的优势包括较低成本。","added":true},{"en":"The advantages of online learning over classroom learning include flexibility.","zh":"线上相比课堂学习的优势包括灵活性。","added":true},{"en":"The advantages of e-books over printed books include easier portability.","zh":"电子书相比纸书的优势包括更方便携带。","added":true}],"questions":[],"references":[]};
